import {useEffect,useId,useRef} from 'react';
import './dialog.css';
type Item={id:string;title:string;summary:string;owner:string;updated:string};
export function MasterDetailDialog({open,items,selected,onSelect,onClose,onConfirm}:{open:boolean;items:Item[];selected:string|null;onSelect:(id:string)=>void;onClose:()=>void;onConfirm:(id:string)=>void}){
 const dialog=useRef<HTMLDialogElement>(null),id=useId();const item=items.find(i=>i.id===selected);
 useEffect(()=>{const node=dialog.current;if(!node)return;if(open&&!node.open){const previous=document.activeElement as HTMLElement|null;node.showModal();return()=>{node.close();previous?.focus()}}if(!open&&node.open)node.close()},[open]);
 return <dialog className="master-dialog" ref={dialog} aria-labelledby={id+'title'} aria-describedby={id+'summary'} onCancel={e=>{e.preventDefault();onClose()}}><header><h1 id={id+'title'}>Choose an item</h1><p id={id+'summary'}>Select an item to review its details, then confirm your choice.</p></header><div className="master-dialog-content"><fieldset><legend>Available items</legend>{items.length===0?<p>No items available.</p>:items.map(i=><label key={i.id}><input type="radio" name={id+'item'} checked={selected===i.id} onChange={()=>onSelect(i.id)}/>{i.title}</label>)}</fieldset><section aria-label="Selected item details" aria-live="polite">{item?<><h2>{item.title}</h2><p>{item.summary}</p><dl><dt>Owner</dt><dd>{item.owner}</dd><dt>Updated</dt><dd>{item.updated}</dd><dt>Identifier</dt><dd>{item.id}</dd></dl></>:<p>Select an item to see its details.</p>}</section></div><footer><button onClick={onClose}>Cancel</button><button disabled={!item} onClick={()=>item&&onConfirm(item.id)}>Use item</button></footer></dialog>;
}
